import {ThinkingTagParser} from '../../infrastructure/parsers/thinkingTagParser.js';
import {validateMessage} from './validation.js';
import type {ValidationResult} from './validation.js';
import {sendCommit, sendDelta, sendError, sendJson, sendSkip, sendStreamEnd, sendUpsert} from './sender.js';
import {log} from '../../shared/logger.js';
import {PerSessionLock} from '../../shared/perSessionLock.js';

interface StreamState {
  thinkingIndex: number | null;
  assistantIndex: number | null;
  responseSuppressed: boolean;
  sentEntryIndices: Set<number>;
  skippedEntryIndices: Set<number>;
}

interface TurnContext {
  ws: WebSocket;
  session: ChatSession;
  state: StreamState;
  parser: ThinkingTagParser;
}

export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
  const lock = new PerSessionLock();
  return function handleMessage(
    ws: WebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
    }
    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
    return wsErrorHandler(ws, () => answerFrame(ws, session, sessionStore, validation));
  };
}

// A turn dropped because its socket closed before its turn came sends nothing, not even stream_end.
async function answerInTurn(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  validation: ValidationResult,
  signal: AbortSignal | undefined
): Promise<void> {
  if (ws.readyState === WebSocket.CLOSED || signal?.aborted) return;
  try {
    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
  } finally {
    endTurn(ws, signal);
  }
}

// No stream_end once the socket has closed: nobody is left to read it (specs/hal-engine-abandon-on-close/spec.md).
function endTurn(ws: WebSocket, signal: AbortSignal | undefined): void {
  if (ws.readyState === WebSocket.CLOSED || signal?.aborted) return;
  sendStreamEnd(ws);
}

// Only a user_message reaches here; an invalid one still takes the error path inside the session's turn.
async function answerUserMessage(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  validation: ValidationResult,
  signal: AbortSignal | undefined
): Promise<void> {
  if (validation.valid && validation.data.type === 'user_message') {
    return handleUserMessage(ws, session, orchestrator, validation.data.content, signal);
  }
  await answerFrame(ws, session, undefined, validation);
}

async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  validation: ValidationResult
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') await handleListSessions(ws, session, sessionStore, message);
}

function commitOpenEntries({ws, session, state}: TurnContext): void {
  commitAndClear(ws, session, state, 'thinkingIndex');
  commitAndClear(ws, session, state, 'assistantIndex');
}

function handlePing(ws: WebSocket, timestamp: number): void {
  ws.send(JSON.stringify({type: 'pong', timestamp}));
}

async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  try {
    const summaries =
      (await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before})) ?? [];
    sendJson(ws, {type: 'session_list', sessions: summaries.map(toSummaryFrame)});
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    log.error('ws', 'session list failed', {userId: session.userId, error: reason});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list sessions');
  }
}

function toSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
  return {
    sessionId: summary.sessionId,
    createdAt: summary.createdAt.toISOString(),
    updatedAt: summary.updatedAt.toISOString(),
    entryCount: summary.entryCount,
  };
}

