const askAfterConnect = async (url: string, outbound: unknown): Promise<{frames: WireFrame[]}> => {
  const client = connectClient(url);
  const frames: WireFrame[] = [];
  await new Promise<void>(resolve => {
    client.on('close', () => resolve());
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as WireFrame;
      if (frame.type === 'pong') {
        client.close();
        return;
      }
      if (frame.type !== 'connected') {
        frames.push(frame);
        return;
      }
      client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
    });
  });
  return {frames};
};

